// The first race's own venue (public/game/venues.js FIRST_VENUE): a newcomer's first race is sailed there, in an
// Optimist, wherever today's race is. Not one of VENUES: never today's race, nor on the set-up page, the venues' pages
// or the passport; known here for the result of a first race (its name, its finish scene's land)
export const FIRST_VENUE: Omit<(typeof VENUES)[number], 'id'> & { id: 'tobago-cays' } = {
  id: 'tobago-cays', name: ['Tobago Cays', 'Тобаго-Кейс', 'Cayos de Tobago', 'Tobago Cays', 'Tobago Cays', 'Tobago Cays', 'Tobago Cays'], nation: 'VCT',
  place: ['St Vincent and the Grenadines', 'Сент-Винсент и Гренадины', 'San Vicente y las Granadinas', 'St. Vincent und die Grenadinen', 'Saint Vincent ve Grenadinler', 'Saint-Vincent-et-les-Grenadines', 'Saint Vincent e Grenadine'],
  wind: ['E', 'В', 'E', 'O', 'D', 'E', 'E'], skip: ['medium', 'long'],
  about: ['A lagoon inside Horseshoe Reef among four uninhabited palm cays, in the steady easterly trade wind.', 'Лагуна за рифом Хорсшу среди четырёх необитаемых пальмовых островков, под ровным восточным пассатом.', 'Una laguna tras el arrecife Horseshoe entre cuatro cayos de palmeras deshabitados, con el alisio constante del este.', 'Eine Lagune hinter dem Horseshoe Reef zwischen vier unbewohnten Palmeninseln, im stetigen Ostpassat.', 'Horseshoe Resifi’nin ardında, ıssız dört palmiyeli adacığın arasında bir lagün, düzenli doğu alize rüzgârında.', 'Un lagon à l’abri de Horseshoe Reef parmi quatre îlots inhabités plantés de palmiers, dans l’alizé d’est régulier.', 'Una laguna dentro la Horseshoe Reef tra quattro isolotti di palme disabitati, con il costante aliseo da est.'],
};
export const venueOf = (id: string | undefined) => VENUES.find((v) => v.id === id) || VENUES[0];
// where a race was sailed, the first race's venue among them (a result, its finish scene); venueOf for the set-up's
export type PlaceId = VenueId | typeof FIRST_VENUE.id;
export const sailedAt = (id: string | undefined) => (id === FIRST_VENUE.id ? FIRST_VENUE : venueOf(id));
// whether the set-up offers a course shape at the venue at that length, as public/game/venues.js shapeOffered
export const shapeOffered = (id: string | undefined, shape: string, length: string) => !(venueOf(id).skip || []).includes(`${shape}:${length}`);
// and whether it offers that length at all, as public/game/venues.js lengthOffered
export const lengthOffered = (id: string | undefined, length: string) => !(venueOf(id).skip || []).includes(length);
